      <div class="topbar__product">
        Upande GoodWe
        <small>Real-time Solar Monitoring</small>
      </div>
      <nav class="topbar__nav">
        <a href="monitors.html" class="on">Monitors</a>
        <a href="inverters.html">Inverters</a>
      </nav>
    </div>
    <div class="topbar__right">
      <span>system@upande.com</span>
      <div class="avatar">GW</div>
    </div>
  </div>

  <div class="page">
    <div class="pagehead">
      <div>
        <div class="pagehead__eyebrow">Upande GoodWe Integration</div>
        <h1 class="pagehead__title">GoodWe Monitors</h1>
        <p class="pagehead__sub">Real-time system metric aggregations & multi-inverter averages</p>
      </div>
      <div class="pagehead__tools">
        <span class="datepill" id="last-sync">Loading...</span>
        <button class="iconbtn" id="refresh-btn" title="Refresh Data">↻</button>
      </div>
    </div>

    <!-- Navigation Pills/Tabs -->
    <div class="tabs">
      <a href="monitors.html" class="tab on">
        <svg viewBox="0 0 24 24"><path d="M18 20V10M12 20V4M6 20v-6"></path></svg> Overview & Averages
      </a>
      <a href="inverters.html" class="tab">
        <svg viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect><line x1="8" y1="21" x2="16" y2="21"></line><line x1="12" y1="17" x2="12" y2="21"></line></svg> Inverter Fleet
      </a>
    </div>

    <!-- KPI Cards -->
    <div class="kpi-grid">
      <div class="kpi">
        <div class="kpi__label">Average Power</div>
