        }

        groupedByTime[timeKey].count += 1;
        groupedByTime[timeKey].current_power_kw += Number(r.current_power_kw) || 0;
        groupedByTime[timeKey].load_power_kw += Number(r.load_power_kw) || 0;
        groupedByTime[timeKey].daily_energy_kwh += Number(r.daily_energy_kwh) || 0;
        groupedByTime[timeKey].battery_soc += Number(r.battery_soc) || 0;
        groupedByTime[timeKey].battery_power_kw += Number(r.battery_power_kw) || 0;
        groupedByTime[timeKey].grid_power_kw += Number(r.grid_power_kw) || 0;
      });

      // Calculate averages per timestamp and sort chronologically
      const timeKeysSorted = Object.keys(groupedByTime).sort().slice(-20);

      const averagedSeries = timeKeysSorted.map(t => {
        const item = groupedByTime[t];
        const cnt = item.count || 1;
        return {
          time: t.split(" ")[1]?.substring(0, 5) || t,
          current_power_kw: item.current_power_kw / cnt,
          load_power_kw: item.load_power_kw / cnt,
          daily_energy_kwh: item.daily_energy_kwh / cnt,
          battery_soc: item.battery_soc / cnt,
          battery_power_kw: item.battery_power_kw / cnt,
          grid_power_kw: item.grid_power_kw / cnt
        };
      });

      const timeLabels = averagedSeries.map(s => s.time);

      // 1. Power Output & Load Chart (Averaged Line Chart)
      createOrUpdateChart("chart-power-output", {
        type: 'line',
        data: {
          labels: timeLabels,
          datasets: [
            {
              label: 'Avg Solar Output (kW)',
              data: averagedSeries.map(s => s.current_power_kw),
              borderColor: '#7aa23f',
              backgroundColor: 'rgba(122, 162, 63, 0.12)',
              fill: true,
              tension: 0.35,
              borderWidth: 2
            },
            {
              label: 'Avg Load Power (kW)',
              data: averagedSeries.map(s => s.load_power_kw),
              borderColor: '#b08d55',
              backgroundColor: 'rgba(176, 141, 85, 0.08)',
              fill: true,
              tension: 0.35,
              borderWidth: 2
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { position: 'bottom', labels: { boxWidth: 12 } } },
          scales: {
            x: { grid: { display: false } },
            y: { beginAtZero: true }
          }
        }
      });

      // 2. Daily Energy Chart (Averaged Bar Chart)
      createOrUpdateChart("chart-daily-energy", {
        type: 'bar',
        data: {
          labels: timeLabels,
          datasets: [{
            label: 'Avg Daily Energy (kWh)',
            data: averagedSeries.map(s => s.daily_energy_kwh),
            backgroundColor: '#44631f',
            borderRadius: 6
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            x: { grid: { display: false } },
            y: { beginAtZero: true }
          }
        }
      });

      // 3. Battery SOC Chart (Average SOC across all inverters)
      const avgLatestSOC = Math.round(
        latestDevices.reduce((sum, r) => sum + (Number(r.battery_soc) || 0), 0) / (latestDevices.length || 1)
      );

      createOrUpdateChart("chart-battery-soc", {
        type: 'doughnut',
        data: {
          labels: ['Avg SOC', 'Remaining'],
          datasets: [{
            data: [avgLatestSOC, Math.max(0, 100 - avgLatestSOC)],
            backgroundColor: ['#7aa23f', 'rgba(10,10,10,0.06)'],
            borderWidth: 0
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          cutout: '75%',
          plugins: {
            legend: { display: false },
            tooltip: { enabled: false }
          }
        },
        plugins: [{
          id: 'textInside',
          afterDraw: function(chart) {
            const width = chart.width, height = chart.height, ctx = chart.ctx;
            ctx.restore();
            ctx.font = "bold 28px Poppins, sans-serif";
            ctx.textBaseline = "middle";
            ctx.fillStyle = "#0a0a0a";
            const text = avgLatestSOC + "%",
                  textX = Math.round((width - ctx.measureText(text).width) / 2),
                  textY = height / 2;
            ctx.fillText(text, textX, textY);
            ctx.save();
          }
        }]
      });

      // 4. Battery Power Chart (Averaged Line Chart)
      createOrUpdateChart("chart-battery-power", {
        type: 'line',
        data: {
          labels: timeLabels,
          datasets: [{
            label: 'Avg Battery Power (kW)',
            data: averagedSeries.map(s => s.battery_power_kw),
            borderColor: '#d9962e',
            backgroundColor: 'rgba(217, 150, 46, 0.12)',
            fill: true,
            tension: 0.3,
            borderWidth: 2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            x: { grid: { display: false } },
            y: { beginAtZero: true }
          }
        }
      });

      // 5. Grid Power Chart (Averaged Bar Chart)
      createOrUpdateChart("chart-grid-power", {
        type: 'bar',
        data: {
          labels: timeLabels,
          datasets: [{
            label: 'Avg Grid Power (kW)',
            data: averagedSeries.map(s => s.grid_power_kw),
            backgroundColor: '#c4302b',
            borderRadius: 6
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            x: { grid: { display: false } },
            y: { beginAtZero: true }
          }
        }
      });

    } catch (error) {
      console.error("GoodWe Monitors error:", error);
    }
  }

  document.getElementById("refresh-btn").addEventListener("click", loadDashboard);
  loadDashboard();
  setInterval(loadDashboard, REFRESH_INTERVAL);
});

