  document.addEventListener("DOMContentLoaded", function () {
    const REFRESH_INTERVAL = 60000;
    const chartInstances = {};

    function format(value, decimals = 1) {
      if (value === null || value === undefined || value === "") return "—";
      return Number(value).toLocaleString(undefined, {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals
      });
    }

    function createOrUpdateChart(chartId, config) {
      if (chartInstances[chartId]) {
        chartInstances[chartId].destroy();
      }
      const canvas = document.getElementById(chartId);
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      chartInstances[chartId] = new Chart(ctx, config);
    }

    async function loadDashboard() {
      try {
        let readings = [];
        if (typeof frappe !== 'undefined') {
          const response = await frappe.call({
            method: "frappe.client.get_list",
            args: {
              doctype: "GoodWe Reading",
              fields: [
                "name", "inverter", "reading_time", "current_power_kw",
                "daily_energy_kwh", "total_energy_kwh", "grid_power_kw",
                "load_power_kw", "battery_soc", "battery_power_kw", "status", "sync_time"
              ],
              order_by: "reading_time desc",
              limit_page_length: 1000
            }
          });
          readings = response.message || [];
        } else {
          // Fallback mock data for development preview
          readings = [
            { inverter: "INV-01", reading_time: "2026-09-08 12:00", current_power_kw: 12.4, daily_energy_kwh: 45.2, total_energy_kwh: 1200, grid_power_kw: 1.2, load_power_kw: 10.1, battery_soc: 85, battery_power_kw: 2.1, sync_time: "2026-09-08 12:00" },
            { inverter: "INV-02", reading_time: "2026-09-08 12:00", current_power_kw: 14.1, daily_energy_kwh: 48.6, total_energy_kwh: 1350, grid_power_kw: 0.8, load_power_kw: 11.5, battery_soc: 88, battery_power_kw: 2.3, sync_time: "2026-09-08 12:00" },
            { inverter: "INV-01", reading_time: "2026-09-08 11:45", current_power_kw: 10.2, daily_energy_kwh: 41.0, total_energy_kwh: 1195, grid_power_kw: 2.1, load_power_kw: 9.8, battery_soc: 82, battery_power_kw: 1.8, sync_time: "2026-09-08 11:45" },
            { inverter: "INV-02", reading_time: "2026-09-08 11:45", current_power_kw: 11.8, daily_energy_kwh: 43.1, total_energy_kwh: 1342, grid_power_kw: 1.5, load_power_kw: 10.2, battery_soc: 84, battery_power_kw: 1.9, sync_time: "2026-09-08 11:45" }
          ];
        }

        if (!readings.length) return;

        const latestPerInverter = {};
        readings.forEach(r => {
          if (!latestPerInverter[r.inverter]) latestPerInverter[r.inverter] = r;
        });
        const latestDevices = Object.values(latestPerInverter);

        const avgPower = latestDevices.reduce((sum, r) => sum + (Number(r.current_power_kw) || 0), 0) / latestDevices.length;
        const peakPower = Math.max(...latestDevices.map(r => Number(r.current_power_kw) || 0));
        const dailyEnergy = latestDevices.reduce((sum, r) => sum + (Number(r.daily_energy_kwh) || 0), 0) / latestDevices.length;
        const totalEnergy = latestDevices.reduce((sum, r) => sum + (Number(r.total_energy_kwh) || 0), 0) / latestDevices.length;

        document.getElementById("avg-power").textContent = format(avgPower);
        document.getElementById("peak-power").textContent = format(peakPower);
        document.getElementById("daily-energy").textContent = format(dailyEnergy);
        document.getElementById("total-energy").textContent = format(totalEnergy);

        const latestSync = latestDevices.map(r => r.sync_time).filter(Boolean).sort().reverse()[0];
        document.getElementById("last-sync").textContent = latestSync ? "Sync " + latestSync.split(" ")[1]?.substring(0, 5) : "No sync";

        const groupedByTime = {};
        readings.forEach(r => {
          const timeKey = r.reading_time || r.sync_time;
          if (!timeKey) return;

          if (!groupedByTime[timeKey]) {
            groupedByTime[timeKey] = { count: 0, current_power_kw: 0, load_power_kw: 0, daily_energy_kwh: 0, battery_soc: 0, battery_power_kw: 0, grid_power_kw: 0 };
          }

          groupedByTime[timeKey].count += 1;
          groupedByTime[timeKey].current_power_kw += Number(r.current_power_kw) || 0;
          groupedByTime[timeKey].load_power_kw += Number(r.load_power_kw) || 0;
          groupedByTime[timeKey].daily_energy_kwh += Number(r.daily_energy_kwh) || 0;
          groupedByTime[timeKey].battery_soc += Number(r.battery_soc) || 0;
          groupedByTime[timeKey].battery_power_kw += Number(r.battery_power_kw) || 0;
          groupedByTime[timeKey].grid_power_kw += Number(r.grid_power_kw) || 0;
        });

        const timeKeysSorted = Object.keys(groupedByTime).sort().slice(-20);
        const averagedSeries = timeKeysSorted.map(t => {
          const item = groupedByTime[t];
          const cnt = item.count || 1;
          return {
            time: t.split(" ")[1]?.substring(0, 5) || t,
            current_power_kw: item.current_power_kw / cnt,
            load_power_kw: item.load_power_kw / cnt,
            daily_energy_kwh: item.daily_energy_kwh / cnt,
            battery_soc: item.battery_soc / cnt,
            battery_power_kw: item.battery_power_kw / cnt,
            grid_power_kw: item.grid_power_kw / cnt
          };
        });

        const timeLabels = averagedSeries.map(s => s.time);

        createOrUpdateChart("chart-power-output", {
          type: 'line',
          data: {
            labels: timeLabels,
            datasets: [
              { label: 'Avg Solar Output (kW)', data: averagedSeries.map(s => s.current_power_kw), borderColor: '#228883', backgroundColor: 'rgba(34, 136, 131, 0.12)', fill: true, tension: 0.35, borderWidth: 2 },
              { label: 'Avg Load Power (kW)', data: averagedSeries.map(s => s.load_power_kw), borderColor: '#0a0a0a', backgroundColor: 'rgba(10, 10, 10, 0.05)', fill: true, tension: 0.35, borderWidth: 2 }
            ]
          },
          options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom' } }, scales: { x: { grid: { display: false } }, y: { beginAtZero: true } } }
        });

        createOrUpdateChart("chart-daily-energy", {
          type: 'bar',
          data: {
