javascript:
frappe.ready(function () {
  const REFRESH_INTERVAL = 60000;
  let allDevices = [];

  function format(value, decimals = 1) {
    if (value === null || value === undefined || value === "") return "—";
    return Number(value).toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals
    });
  }

  function updateMetricsAndCards(selectedInverter) {
    const devices = selectedInverter === "all" 
      ? allDevices 
      : allDevices.filter(d => d.inverter === selectedInverter);

    if (!devices.length) {
      document.getElementById("device-grid").innerHTML = '<div class="gw-loading">No readings found.</div>';
      return;
    }

    const pvPower = devices.reduce((sum, r) => sum + (Number(r.current_power_kw) || 0), 0);
    const loadPower = devices.reduce((sum, r) => sum + (Number(r.load_power_kw) || 0), 0);
    const gridPower = devices.reduce((sum, r) => sum + (Number(r.grid_power_kw) || 0), 0);
    const batteryPower = devices.reduce((sum, r) => sum + (Number(r.battery_power_kw) || 0), 0);
    const dailyEnergy = Math.max(...devices.map(r => Number(r.daily_energy_kwh) || 0));
    const totalEnergy = Math.max(...devices.map(r => Number(r.total_energy_kwh) || 0));
    const batterySOC = devices.reduce((sum, r) => sum + (Number(r.battery_soc) || 0), 0) / devices.length;
    const online = devices.filter(r => r.status === "Online").length;

    document.getElementById("pv-power").textContent = format(pvPower);
    document.getElementById("daily-energy").textContent = format(dailyEnergy);
    document.getElementById("total-energy").textContent = format(totalEnergy);
    document.getElementById("battery-soc").textContent = format(batterySOC);
    document.getElementById("load-power").textContent = format(loadPower);
    document.getElementById("grid-power").textContent = format(gridPower);
    document.getElementById("battery-power").textContent = format(batteryPower);
    document.getElementById("online-count").textContent = online;
    document.getElementById("device-count").textContent = devices.length + " devices";

    const grid = document.getElementById("device-grid");
    grid.innerHTML = devices.map(r => {
      const statusClass = r.status === "Online" ? "online" : "offline";
      return `
        <div class="gw-device">
          <div class="gw-device-head">
            <div class="gw-device-name">${frappe.utils.escape_html(r.inverter || "Unknown")}</div>
            <span class="gw-status ${statusClass}">${frappe.utils.escape_html(r.status || "Unknown")}</span>
          </div>

          <div class="gw-device-stats">
            <div class="gw-device-stat">
              <small>Power</small>
              <b>${format(r.current_power_kw)} kW</b>
            </div>
            <div class="gw-device-stat">
              <small>Battery</small>
              <b>${format(r.battery_soc, 0)}%</b>
            </div>
            <div class="gw-device-stat">
              <small>Load</small>
              <b>${format(r.load_power_kw)} kW</b>
            </div>
            <div class="gw-device-stat">
              <small>Grid</small>
              <b>${format(r.grid_power_kw)} kW</b>
            </div>
          </div>
        </div>
      `;
    }).join("");
  }

  function populateFilterOptions(devices) {
    const filterSelect = document.getElementById("inverter-filter");
    const currentSelection = filterSelect.value;
    filterSelect.innerHTML = '<option value="all">All Inverters</option>';

    devices.forEach(d => {
      const opt = document.createElement("option");
      opt.value = d.inverter;
      opt.textContent = d.inverter;
      filterSelect.appendChild(opt);
    });

    filterSelect.value = currentSelection || "all";
  }

  async function loadDashboard() {
    try {
      const response = await frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "GoodWe Reading",
          fields: [
            "name", "inverter", "reading_time", "current_power_kw",
            "daily_energy_kwh", "total_energy_kwh", "grid_power_kw",
            "load_power_kw", "battery_soc", "battery_power_kw",
            "status", "sync_time"
          ],
          order_by: "reading_time desc",
          limit_page_length: 1000
        }
      });

      const readings = response.message || [];
      const latest = {};
      readings.forEach(r => {
        if (!latest[r.inverter]) latest[r.inverter] = r;
      });

      allDevices = Object.values(latest);

      if (!allDevices.length) {
        document.getElementById("device-grid").innerHTML = '<div class="gw-loading">No GoodWe readings found.</div>';
        return;
      }

      populateFilterOptions(allDevices);
      updateMetricsAndCards(document.getElementById("inverter-filter").value);

      const latestSync = allDevices.map(r => r.sync_time).filter(Boolean).sort().reverse()[0];
      document.getElementById("last-sync").textContent = latestSync
        ? "Updated " + frappe.datetime.prettyDate(latestSync)
        : "No sync time";

    } catch (error) {
      console.error("GoodWe dashboard error:", error);
      document.getElementById("device-grid").innerHTML = '<div class="gw-loading">Unable to load GoodWe readings.</div>';
    }
  }

  document.getElementById("inverter-filter").addEventListener("change", function(e) {
    updateMetricsAndCards(e.target.value);
  });

  document.getElementById("refresh-btn").addEventListener("click", loadDashboard);

  loadDashboard();
  setInterval(loadDashboard, REFRESH_INTERVAL);
});
